"""Context-building policy for solve and propose modes."""
import json


def _encode(value):
    return json.dumps(value, ensure_ascii=False, separators=(',', ':'))


def build_context(payload) -> str:
    mode = payload['mode']
    if mode == 'propose':
        return _encode({
            'goal': 'Improve build_context using development evidence. Return ONLY JSON with hypothesis and strategy_source containing a complete Python module. Treat proposed benefits as unmeasured until evaluated.',
            'current_strategy': payload['source'],
            'development_evidence': payload['evidence'],
            'contract': 'Define build_context(payload) -> str for solve and propose modes. Preserve further strategy proposals. Maximum 200 changed lines. Only this strategy module is mutable. Do not change budgets, tool protocol, evaluator, or acceptance policy.',
            'analysis_guidance': 'Distinguish observed outcomes from hypotheses. Preserve successful behavior; avoid task-specific lookup tables or hardcoded examples. Consider context overhead as well as correctness.'
        })
    if mode == 'solve':
        return _encode({
            'goal': payload['task']['instruction'],
            'files': payload['files'],
            'public_checks': payload['task']['public'],
            'observations': payload['observations'],
            'remaining_steps': payload['remaining_steps'],
            'advice': 'Follow the specification, not the buggy implementation. Make the smallest general repair. Check applicable boundaries: zero/empty inputs, signs, inclusive endpoints, exact types (bool versus int), and floor/ceiling semantics. Prefer exact integer arithmetic when required. Use observations to avoid repeating failed attempts; use public tests when useful. Do not hardcode examples or invent unspecified behavior. Finish once the repair is complete.'
        })
    raise ValueError('Unsupported mode: ' + str(mode))
